function plot(points,labels=[],centers=[],query=null){
 const palette=['#2e65c7','#b2813c','#8f71b6'];
 const max=Math.max(10,...points.flat(),...centers.flat(),...(query||[]))+1,x=v=>40+v/max*460,y=v=>280-v/max*240;
 return `<svg class="pyq-plot" viewBox="0 0 540 320" role="img" aria-label="Labelled coordinate plot. Circles are points, crosses are centres, the outlined square is the query."><path d="M40 30V280H510" fill="none" stroke="#93a8c7"/>${[0,2,4,6,8,10].map(v=>`<g><path d="M${x(v)} 30V280M40 ${y(v)}H510" stroke="#e3eaf5"/><text x="${x(v)}" y="300" text-anchor="middle">${v}</text><text x="25" y="${y(v)+4}">${v}</text></g>`).join('')}${points.map((pt,i)=>`<circle cx="${x(pt[0])}" cy="${y(pt[1])}" r="7" fill="${palette[labels[i]??0]}"/><text x="${x(pt[0])+10}" y="${y(pt[1])-8}">${esc('A'+(i+1))}</text>`).join('')}${centers.map((pt,i)=>`<path d="M${x(pt[0])-9} ${y(pt[1])-9}l18 18m-18 0l18-18" stroke="${palette[i]}" stroke-width="3"/><text x="${x(pt[0])+10}" y="${y(pt[1])+18}">C${i+1}</text>`).join('')}${query?`<rect x="${x(query[0])-10}" y="${y(query[1])-10}" width="20" height="20" fill="white" stroke="#173d82" stroke-width="3"/><text x="${x(query[0])+14}" y="${y(query[1])+5}">Q</text>`:''}</svg><p class="pyq-caption">C1: blue · C2: amber · C3: purple. Point names remain visible for comparison with the table.</p>`;
}
function nbDetails(model){return model.terms.map(r=>`<section class="pyq-subsection"><h4>${esc(r.label)} · prior ${n(r.prior)}</h4>${table(['Feature=value','Matching count','Denominator','Conditional probability'],r.factors.map(f=>[`${f.feature}=${f.value??'present'}`,f.numerator??f.matches,f.denominator,n(f.p)]))}${eq(`score(${r.label}) = ${n(r.prior,6)} × ${r.factors.map(f=>n(f.p,6)).join(' × ')} = ${n(r.score,8)}`)}</section>`).join('');}
