 const select=field('alarmProfile','Document a correction profile',[['unselected','Select a correction assumption'],['keepTrue','Keep printed True probabilities; False = 1 − True'],['keepFalse','Keep printed False probabilities; True = 1 − False'],['normalize','Divide each printed row by its row sum'] ],profile);
