function cvGuide(){const round=Number(c('cvRound','1')),correct=[2,1,2,2,1],folds=Array.from({length:5},(_,i)=>[2*i+1,2*i+2]),acc=correct.map(x=>x/2),mean=acc.reduce((a,b)=>a+b)/5;return {steps:[step('Understand the purpose','Estimate how a learning procedure performs on unseen records.',p('A single train/test split depends on which records happen to be held out. Five-fold cross-validation rotates the validation group so every record is held out once.')+box('New toy practice: ten records and example correct-prediction counts. These are not the lab’s actual Iris results and are not a university PYQ.')),step('Partition the ten records','Each fold contains two distinct records.',table(['Fold','Record IDs'],folds.map((f,i)=>[i+1,f.join(', ')]))+p('Use one fixed partition for the five rounds. The pack describes shuffled KFold; the existing Iris lab uses stratification to balance species across folds. Both use five independent training fits.')),step('Visualise every round','Choose a round and inspect training versus validation.',field('cvRound','Highlighted round',folds.map((_,i)=>[i+1,'Round '+(i+1)]),round)+`<div class="pyq-folds">${folds.map((_,r)=>`<div class="${r+1===round?'selected':''}"><b>Round ${r+1}</b>${folds.map((f,k)=>`<span class="${r===k?'heldout':''}">F${k+1}<small>${r===k?'Validate':'Train'}: ${f.join(',')}</small></span>`).join('')}</div>`).join('')}</div>`+p(`Round ${round}: train on records ${folds.filter((_,i)=>i!==round-1).flat().join(', ')}; validate on ${folds[round-1].join(', ')}. That is 8 training and 2 validation records.`)),step('Fit, predict and score separately','Rebuild the model inside each round.',flow(['4 training folds','Fit preprocessing + model','Predict held-out fold','Record metric'])+box('Prevent leakage: learn scaling, vocabulary, imputation and feature selection on that round’s training records only. Do not tune settings against an untouched final test set.')),step('Average and write the full answer','The example assumes the following correct counts were observed.',table(['Round','Correct / validation','Accuracy'],correct.map((count,i)=>[i+1,`${count}/2`,percent(acc[i])]))+eq(`Mean accuracy = (${acc.join(' + ')}) / 5 = ${n(mean)} = ${percent(mean)}`)+p('Every record appears in validation exactly once and in training four times. Report all five scores and their arithmetic mean. The mean is 80% for these supplied example outcomes; it is an estimate, not a guaranteed future accuracy.'))],quiz:quiz('How many times is each record used for validation?',['Once','Four times','Five times'],0,'With five non-overlapping validation folds, each record is held out in exactly one round.')};}
function colabGuide(){const code=`import pandas as pd\n\ndf = pd.DataFrame({\n    "student": ["A", "B", "C"],\n    "marks": [78, 85, 92]\n})\nprint(df.to_string(index=False))\nprint("Mean marks:", df["marks"].mean())\ndf.to_csv("marks.csv", index=False)`;return {steps:[step('Understand the notebook','A notebook combines explanations, code cells and outputs.',glossary([['Notebook','A saved document containing cells.'],['Runtime','The computer session that runs the Python code.'],['Code cell','A block of executable Python.'],['Output','The printed text, table or chart produced by a cell.']])+box('Practical preparation, not a university PYQ. The app displays an example; it does not run a Colab kernel.')),step('Create and run the example','In Colab, connect a Python runtime and run cells in order.',p('Create or open a notebook in Google Colab. Use a Markdown cell for the experiment aim and a code cell for the Python below. Execute the code cell with its run button or Shift+Enter.')+eq(code)+p('A CPU runtime is sufficient for this example. You can also download the project notebook from Lab Resources.')),step('Inspect the expected output','Compare values and confirm that execution completed.',eq('student  marks\n      A     78\n      B     85\n      C     92\nMean marks: 85.0')+flow(['78 + 85 + 92 = 255','255 / 3 = 85','marks.csv saved'])+box('Expected output for the displayed code. This panel is a walkthrough, not a captured Colab execution.')),step('Save and download','A notebook and a dataset are separate files.',eq('from google.colab import files\nfiles.download("marks.csv")')+p('Save the notebook in Drive or download its .ipynb file. To use a local CSV, upload it to the runtime and read it with pd.read_csv using the actual uploaded filename. Runtime storage can disappear when the session resets; save important files outside it.')),step('Troubleshoot and finish the activity','Explain errors by checking their causes.',table(['Error / problem','Step to resolve it'],[['NameError: df is not defined','Run the import and DataFrame creation cell before later cells.'],['FileNotFoundError','Check the current directory and exact filename; upload the data again after a runtime reset.'],['ModuleNotFoundError','Install the required package in this runtime, then import it.'],['Output from old variables','Restart the runtime and run all cells in order to verify reproducibility.']])+p('A completed activity has the notebook saved, all cells run in order, the three rows and mean 85.0 visible, and marks.csv saved or downloaded. This guide does not assert that those actions have occurred in a separate Colab session.'))],quiz:quiz('Why might df be undefined after reconnecting?',['The code is always invalid','The new runtime has not executed the creation cell'],1,'Notebook cells are saved, but runtime variables are session state. Run the setup cells again.')};}
export function buildGuide(q){
 if(q.kind==='id3')return id3Guide();
 if(['buy','employee','marketing'].includes(q.kind))return categoricalGuide(q);
 if(['fruit','internalFruit'].includes(q.kind))return fruitGuide(q);
 const builders={metrics:metricGuide,alarm:alarmGuide,kmeans:kmeansGuide,comparison:comparisonGuide,hierarchy:hierarchyGuide,silhouette:silhouetteGuide,em:emGuide,emSteps:emGuide,bnTheory:bnTheoryGuide,missing:missingGuide,document:documentGuide,knn:knnGuide,cv:cvGuide,colab:colabGuide};
 if(!builders[q.kind])throw new Error('No guide for '+q.kind);return builders[q.kind](q);
}
function matches(){return questions.filter(q=>(filter==='all'||q.topics.includes(expId))&&(sourceFilter==='all'||(sourceFilter==='pyq'?['paper','transcription'].includes(q.type):sourceFilter==='practice'?['model','practice'].includes(q.type):['internal','bank'].includes(q.type)))&&`${q.title} ${q.id} ${q.session} ${q.text}`.toLowerCase().includes(search.toLowerCase()));}
function questionCards(){const items=matches();return `<div class="pyq-list-count">${items.length} ${items.length===1?'question':'questions'} shown</div>${items.length?items.map(q=>`<button class="pyq-question${q.id===selected?' active':''}" data-pyq-question="${q.id}" ${q.id===selected?'aria-current="true"':''}><span class="pyq-tag ${q.type}">${evidenceLabels[q.type]}${q.related?' · related':''}</span><b>${esc(q.title)}</b><span>${esc(q.session)}${q.marks?` · ${q.marks} marks`:''}</span><small>${q.kind==='missing'?'Original data needed':memory[q.id]?.finished?'Guide reviewed':'Guided solution'} · ${esc(q.id)}</small></button>`).join(''):'<div class="pyq-empty">No questions match. Try all experiments or another evidence filter.</div>'}`;}
function render(){
 const items=matches();if(items.length&&!items.some(q=>q.id===selected))setQuestion(items[0].id);
 const q=items.find(q=>q.id===selected),guide=q?buildGuide(q):null,s=q?current():null;
 if(s&&s.step>=guide.steps.length)s.step=0;
 const reviewed=questions.filter(q=>memory[q.id]?.finished).length;
 host.innerHTML=`<div class="pyq-workspace"><section class="pyq-intro"><div><span class="learn-kicker">FROM FIRST PRINCIPLES TO A COMPLETE ANSWER</span><h2>Previous-year question studio</h2><p>Read the question. Learn the idea. Work through every calculation. Build an answer you can explain.</p></div><div class="pyq-stat"><b>${questions.length}</b><span>guided questions<br>${reviewed} reviewed on this device</span></div></section><div class="pyq-scope">${esc(topicNotes[expId])}</div><details class="pyq-evidence"><summary>Where these questions come from</summary><p>Question text, exam labels and marks are transcribed from your supplied ${sourceName}. “Original-paper transcription” and “secondary transcription” reflect the pack’s evidence claims; original university papers have not been independently authenticated here. Internal papers, model questions and new practice are labelled separately. “No match located” only describes the pack’s available source set.</p><p>Formula references: <a href="https://scikit-learn.org/stable/modules/naive_bayes.html" target="_blank" rel="noopener">Naive Bayes</a> · <a href="https://scikit-learn.org/stable/modules/clustering.html" target="_blank" rel="noopener">Clustering</a> · <a href="https://scikit-learn.org/stable/modules/generated/sklearn.metrics.silhouette_score.html" target="_blank" rel="noopener">Silhouette</a>. New examples and assumption-dependent answers are identified in their guides.</p></details><div class="pyq-toolbar"><label class="pyq-field"><span>Find a question</span><input type="search" data-pyq-search placeholder="Topic, year or question ID…" value="${esc(search)}"></label><label class="pyq-field"><span>Experiment scope</span><select data-pyq-filter><option value="topic" ${filter==='topic'?'selected':''}>This experiment</option><option value="all" ${filter==='all'?'selected':''}>All 8 experiments</option></select></label><label class="pyq-field"><span>Question source</span><select data-pyq-source>${[['all','All sources'],['pyq','University PYQ records'],['other','Internal / question bank'],['practice','Model / new practice']].map(([v,t])=>`<option value="${v}" ${v===sourceFilter?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="pyq-layout"><nav class="pyq-library" aria-label="Question library">${questionCards()}</nav><div class="pyq-detail">${q?renderGuide(q,guide,s):'<section class="card card-body"><h3>No matching questions</h3><p>Change the search or filters to continue.</p></section>'}</div></div></div>`;
 const stepNav=host.querySelector('.pyq-stepnav'),stepButton=stepNav?.querySelector('[aria-current=step]');
 if(stepButton&&stepNav.scrollWidth>stepNav.clientWidth)stepNav.scrollLeft=stepButton.offsetLeft-(stepNav.clientWidth-stepButton.offsetWidth)/2;
 const library=host.querySelector('.pyq-library'),questionButton=library?.querySelector('[aria-current=true]');
 if(questionButton&&library.scrollHeight>library.clientHeight)library.scrollTop=questionButton.offsetTop-(library.clientHeight-questionButton.offsetHeight)/2;
}
function renderGuide(q,guide,s){const active=guide.steps[s.step],done=s.reviewed.length,choice=s.choice,check=choice!=null,correct=choice===guide.quiz.correct;
 const quizHtml=`<section class="pyq-check"><h4>Check your understanding</h4><p>${esc(guide.quiz.question)}</p><div>${guide.quiz.options.map((option,i)=>`<button data-pyq-answer="${i}" class="${check&&choice===i?(correct?'correct':'incorrect'):''}" aria-pressed="${choice===i}">${esc(option)}</button>`).join('')}</div>${check?`<p role="status"><b>${correct?'Correct.':'Try again.'}</b> ${esc(guide.quiz.explanation)}</p>`:''}</section>`;
 return `<article class="pyq-guide"><header class="pyq-question-header"><div class="pyq-tag ${q.type}">${evidenceLabels[q.type]}${q.related?' · related topic':''}</div><div class="pyq-question-meta">221TCS100 · M.Tech · ${esc(q.session)} · ${esc(q.number)}${q.marks?' · '+q.marks+' marks':' · marks unverified'}</div><h3>${esc(q.title)}</h3><p>${esc(q.text)}</p><div class="pyq-source">Source: supplied question pack · page ${q.page}${q.id==='NB-MT25-Q8'?' (warning continues on page 5)':''}. ${q.type==='practice'?'Example created for this app from the suggested activity type.':'Question wording is condensed without changing the task.'}</div>${q.caution?box(esc(q.caution),true):''}<div class="pyq-question-actions"><button class="button" data-pyq-action="print">Print complete worked guide</button><button class="button" data-pyq-action="download">Save answer text</button><button class="button text" data-pyq-action="reset">Restart this guide</button></div></header><div class="pyq-progress"><span>${done}/${guide.steps.length} steps reviewed${s.finished?' · Guide reviewed':''}</span><span>Step ${s.step+1} of ${guide.steps.length}</span><div><i style="width:${done/guide.steps.length*100}%"></i></div></div><nav class="pyq-stepnav" aria-label="Solution steps">${guide.steps.map((t,i)=>`<button data-pyq-step="${i}" ${s.step===i?'aria-current="step"':''}><span>${s.reviewed.includes(i)?'✓':i+1}</span>${esc(t.title)}</button>`).join('')}</nav><section class="pyq-step" aria-label="Current solution step"><span class="learn-kicker">STEP ${s.step+1} · LEARN AND WORK IT OUT</span><h4 tabindex="-1">${esc(active.title)}</h4><p class="pyq-step-intro">${esc(active.intro)}</p><div class="pyq-step-body">${active.html}</div>${s.step===guide.steps.length-1?quizHtml:''}<div class="pyq-navigation"><button class="button" data-pyq-action="previous" ${s.step===0?'disabled':''}>← Previous</button><button class="button primary" data-pyq-action="next">${s.step===guide.steps.length-1?'Mark this step reviewed ✓':'I understand · Next →'}</button></div></section><details class="pyq-full-answer"><summary>View the entire worked solution</summary>${guide.steps.map((t,i)=>`<section><h4>${i+1}. ${esc(t.title)}</h4><p>${esc(t.intro)}</p>${t.html}</section>`).join('')}</details><div class="pyq-print"><h2>${esc(q.title)}</h2><p>${esc(q.session)} · ${esc(q.number)}${q.marks?' · '+q.marks+' marks':''} · ${evidenceLabels[q.type]}</p><p>${esc(q.text)}</p><p>Source: ${sourceName}, page ${q.page}. Evidence labels follow the supplied pack. Assumptions stated below are part of this worked answer.</p>${q.caution?box(esc(q.caution),true):''}${guide.steps.map((t,i)=>`<section><h3>${i+1}. ${esc(t.title)}</h3><p>${esc(t.intro)}</p>${t.html}</section>`).join('')}</div></article>`;
}
export function mountPYQ(panel,data,id,helpers){
 controller?.abort();controller=new AbortController();const signal=controller.signal;host=panel;expId=id;ui=helpers;memory=loadMemory();filter='topic';sourceFilter='all';search='';
 const requested=new URLSearchParams(location.hash.slice(1)).get('question');selected=questions.find(q=>q.id===requested)?.id||questions.find(q=>q.topics.includes(id)).id;
 if(requested&&!questions.find(q=>q.id===requested)?.topics.includes(id))filter='all';render();
 host.addEventListener('click',event=>{
  const question=event.target.closest('[data-pyq-question]');if(question){setQuestion(question.dataset.pyqQuestion);render();return;}
  const nav=event.target.closest('[data-pyq-step]');if(nav){current().step=Number(nav.dataset.pyqStep);save();render();focusStep();return;}
  const answer=event.target.closest('[data-pyq-answer]');if(answer){current().choice=Number(answer.dataset.pyqAnswer);save();render();return;}
  const action=event.target.closest('[data-pyq-action]')?.dataset.pyqAction;if(!action)return;
  const s=current(),q=questions.find(q=>q.id===selected),g=buildGuide(q);
  if(action==='previous'){s.step=Math.max(0,s.step-1);save();render();focusStep();}
  if(action==='next'){if(!s.reviewed.includes(s.step))s.reviewed.push(s.step);if(s.step===g.steps.length-1)s.finished=s.reviewed.length===g.steps.length;else s.step++;save();render();focusStep();}
  if(action==='reset'){memory[selected]={step:0,reviewed:[],controls:{},choice:null};save();render();}
  if(action==='print')window.print();
  if(action==='download'){const node=host.querySelector('.pyq-print');const clone=node.cloneNode(true);clone.querySelectorAll('select').forEach(el=>el.replaceWith(document.createTextNode(el.selectedOptions[0]?.textContent||'')));clone.querySelectorAll('svg').forEach(el=>el.replaceWith(document.createTextNode('[Coordinate plot: view in the app.]\n')));clone.querySelectorAll('td,th').forEach(el=>el.append('\t'));clone.querySelectorAll('p,pre,h2,h3,h4,li,tr,dt,dd,section,div,label').forEach(el=>el.append('\n'));ui.downloadText(clone.textContent.replace(/\n{3,}/g,'\n\n'),q.id+'-worked-answer.txt');}
 },{signal});
 host.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-pyq-filter]'))filter=el.value;else if(el.matches('[data-pyq-source]'))sourceFilter=el.value;else if(el.matches('[data-pyq-control]')){current().controls[el.dataset.pyqControl]=el.value;current().finished=false;save();}else return;render();},{signal});
 host.addEventListener('input',event=>{if(!event.target.matches('[data-pyq-search]'))return;search=event.target.value;const input=event.target,start=input.selectionStart;render();const next=host.querySelector('[data-pyq-search]');next.focus();try{next.setSelectionRange(start,start);}catch{}},{signal});
}
function focusStep(){const heading=host.querySelector('.pyq-step>h4');heading?.focus({preventScroll:true});heading?.scrollIntoView({behavior:'smooth',block:'nearest'});}
// Test-only data hooks: pure builders use this state and never require a browser.
export function inspectGuide(id,controls={}){selected=id;memory={[id]:{step:0,reviewed:[],controls,choice:null}};return buildGuide(questions.find(q=>q.id===id));}
